<script setup lang="ts">
import { router } from '@inertiajs/vue3'; import { ArrowLeft, Check, Pencil, Send, X } from 'lucide-vue-next'; import { computed, ref } from 'vue'; import { useI18n } from 'vue-i18n'; import Button from '@/Core/Components/Button.vue'; import Card from '@/Core/Components/Card.vue'; import ConfirmDialog from '@/Core/Components/ConfirmDialog.vue'; import DataTable, { type Column } from '@/Core/Components/DataTable.vue'; import PageHeader from '@/Core/Components/PageHeader.vue'; import { useFormat } from '@/Core/composables/useFormat'; import TenantLayout from '@/Core/Layouts/TenantLayout.vue'; import { route } from '@/Core/lib/route'; import CrmStatusBadge from '../../../Components/CrmStatusBadge.vue'; import QuoteFormDialog from '../../../Components/QuoteFormDialog.vue'; import SalesNav from '../../../Components/SalesNav.vue'; import type { Quote, QuoteFormOptions } from '../../../Components/types';
defineOptions({ layout: TenantLayout }); const props = defineProps<{ quote: Quote; form: QuoteFormOptions }>(); const { t } = useI18n(); const format = useFormat(); const editOpen = ref(false); const action = ref<'send' | 'accept' | 'reject' | 'cancel' | null>(null); const working = ref(false); const columns = computed<Column[]>(() => [{ key: 'name', label: t('crm.fields.name') }, { key: 'quantity', label: t('crm.sales.quotes.quantity'), align: 'right' }, { key: 'price', label: t('crm.fields.unitPrice'), align: 'right' }, { key: 'discount', label: t('crm.sales.quotes.discount'), align: 'right' }, { key: 'total', label: t('crm.sales.quotes.total'), align: 'right' }]);
function perform(): void { if (!action.value) return; working.value = true; router.post(route(`crm.sales.quotes.${action.value}`, { quote: props.quote.id }), {}, { preserveScroll: true, onFinish: () => { working.value = false; action.value = null; } }); }
</script>
<template><PageHeader :eyebrow="quote.number" :title="quote.title" :description="quote.company?.name ?? quote.contact?.name ?? t('crm.common.notSet')"><template #actions><Button variant="ghost" :href="route('crm.sales.quotes.index')"><template #icon><ArrowLeft class="size-4" aria-hidden="true" /></template>{{ t('crm.sales.quotes.title') }}</Button><Button v-if="quote.editable" @click="editOpen = true"><template #icon><Pencil class="size-4" aria-hidden="true" /></template>{{ t('crm.common.edit') }}</Button><Button v-if="quote.editable" variant="primary" @click="action = 'send'"><template #icon><Send class="size-4" aria-hidden="true" /></template>{{ t('crm.sales.quotes.send') }}</Button><Button v-if="quote.acceptable" variant="primary" @click="action = 'accept'"><template #icon><Check class="size-4" aria-hidden="true" /></template>{{ t('crm.sales.quotes.accept') }}</Button><Button v-if="quote.rejectable" variant="danger" @click="action = 'reject'"><template #icon><X class="size-4" aria-hidden="true" /></template>{{ t('crm.sales.quotes.reject') }}</Button><Button v-if="quote.cancelable" variant="ghost" @click="action = 'cancel'"><template #icon><X class="size-4" aria-hidden="true" /></template>{{ t('crm.sales.quotes.cancel') }}</Button></template></PageHeader><SalesNav current="quotes" /><div class="grid gap-3 xl:grid-cols-[minmax(0,2fr)_20rem]"><Card :title="t('crm.sales.quotes.lines')" flush><DataTable :columns="columns" :rows="quote.lines" row-key="id" :caption="t('crm.sales.quotes.lines')"><template #cell-name="{ row }"><div><p class="font-medium text-ink">{{ row.name }}</p><p v-if="row.sku" class="font-mono text-xs text-ink-subtle">{{ row.sku }}</p></div></template><template #cell-quantity="{ row }"><span class="tabular font-mono">{{ format.number(row.quantityMilli / 1000) }} {{ row.unit }}</span></template><template #cell-price="{ row }"><span class="tabular font-mono">{{ format.money(row.unitPriceAmount, row.currency) }}</span></template><template #cell-discount="{ row }"><span class="tabular font-mono">{{ format.money(row.discountAmount, row.currency) }}</span></template><template #cell-total="{ row }"><span class="tabular font-mono font-semibold">{{ format.money(row.lineTotalAmount, row.currency) }}</span></template></DataTable></Card><div class="grid content-start gap-3"><Card><div class="flex justify-between gap-3"><span class="text-ink-muted">{{ t('crm.fields.status') }}</span><CrmStatusBadge :status="quote.status" /></div><dl class="mt-4 grid gap-2 text-sm"><div class="flex justify-between gap-3"><dt class="text-ink-muted">{{ t('crm.sales.quotes.subtotal') }}</dt><dd class="tabular font-mono">{{ format.money(quote.subtotalAmount, quote.currency) }}</dd></div><div class="flex justify-between gap-3"><dt class="text-ink-muted">{{ t('crm.sales.quotes.discount') }}</dt><dd class="tabular font-mono">{{ format.money(quote.discountAmount, quote.currency) }}</dd></div><div class="flex justify-between gap-3"><dt class="text-ink-muted">{{ t('crm.sales.quotes.tax') }}</dt><dd class="tabular font-mono">{{ format.money(quote.taxAmount, quote.currency) }}</dd></div><div class="mt-2 flex justify-between gap-3 border-t border-line pt-3 text-base font-semibold"><dt>{{ t('crm.sales.quotes.total') }}</dt><dd class="tabular font-mono">{{ format.money(quote.totalAmount, quote.currency) }}</dd></div></dl></Card><Card v-if="quote.terms || quote.notes" :title="t('crm.fields.description')"><p v-if="quote.terms" class="whitespace-pre-wrap text-sm text-ink">{{ quote.terms }}</p><p v-if="quote.notes" class="mt-3 whitespace-pre-wrap text-sm text-ink-muted">{{ quote.notes }}</p></Card></div></div><QuoteFormDialog v-if="quote.editable" v-model:open="editOpen" :quote="quote" :options="form" /><ConfirmDialog :open="action !== null" :title="action ? t(`crm.sales.quotes.${action}`) : ''" :description="quote.title" :confirm-label="action ? t(`crm.sales.quotes.${action}`) : ''" :loading="working" @update:open="!$event && (action = null)" @confirm="perform" /></template>
